import { DatabaseSync } from 'node:sqlite';
function main(): void {
  const db = new DatabaseSync(':memory:');
  const stmt = db.prepare('SELECT 1 AS one');
  console.log(db.isOpen, JSON.stringify(stmt.get()));
  db.close();
  console.log(db.isOpen);
  try { db.close(); } catch (e: any) { console.log(e.code, e.message); }
  try { stmt.get(); } catch (e: any) { console.log(e.code, e.message); }
  try { db.exec('SELECT 1'); } catch (e: any) { console.log(e.code, e.message); }
  db.open();
  console.log(db.isOpen);
  try { db.open(); } catch (e: any) { console.log(e.code, e.message); }
  db.close();
}
